-- CHAMBA 053 — Chat cliente↔técnico con login teléfono (mismo canal que agenda 046)-- Problema: job_chat_* exigía auth.uid() = created_by/assigned_worker_id exacto;-- sin JWT o con perfil duplicado por teléfono, no se podía leer ni enviar mensajes.SET statement_timeout = '120s';CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS fn_profiles_same_phone CASCADE;CREATE OR REPLACE FUNCTION fn_profiles_same_phone(p_a UUID, p_b UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM profiles a    JOIN profiles b ON a.id = p_a AND b.id = p_b    WHERE a.phone IS NOT NULL      AND b.phone IS NOT NULL      AND regexp_replace(a.phone, '\D', '', 'g')        = regexp_replace(b.phone, '\D', '', 'g')  );$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_user_matches CASCADE;CREATE OR REPLACE FUNCTION job_chat_user_matches(p_profile_id UUID, p_user_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT p_profile_id IS NOT NULL    AND p_user_id IS NOT NULL    AND (      p_profile_id = p_user_id      OR fn_profiles_same_phone(p_profile_id, p_user_id)    );$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_actor_is CASCADE;CREATE OR REPLACE FUNCTION job_chat_actor_is(p_profile_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT job_chat_user_matches(p_profile_id, auth.uid());$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_is_participant CASCADE;CREATE OR REPLACE FUNCTION job_chat_is_participant(p_servicio_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM jobs j    WHERE j.id = p_servicio_id      AND j.status <> 'cancelled'      AND (        job_chat_actor_is(j.created_by)        OR job_chat_actor_is(j.assigned_worker_id)        OR EXISTS (          SELECT 1          FROM job_assignments ja          WHERE ja.job_id = j.id            AND job_chat_actor_is(ja.worker_id)            AND ja.selection_status = 'approved'        )      )  );$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_is_writable CASCADE;CREATE OR REPLACE FUNCTION job_chat_is_writable(p_servicio_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM jobs j    WHERE j.id = p_servicio_id      AND j.status IN ('taken', 'in_progress')      AND (        job_chat_actor_is(j.created_by)        OR job_chat_actor_is(j.assigned_worker_id)        OR EXISTS (          SELECT 1          FROM job_assignments ja          WHERE ja.job_id = j.id            AND job_chat_actor_is(ja.worker_id)            AND ja.selection_status = 'approved'        )      )  );$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_user_can_access CASCADE;CREATE OR REPLACE FUNCTION job_chat_user_can_access(  p_servicio_id UUID,  p_user_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM jobs j    WHERE j.id = p_servicio_id      AND j.status <> 'cancelled'      AND (        job_chat_user_matches(j.created_by, p_user_id)        OR job_chat_user_matches(j.assigned_worker_id, p_user_id)        OR EXISTS (          SELECT 1          FROM job_assignments ja          WHERE ja.job_id = j.id            AND job_chat_user_matches(ja.worker_id, p_user_id)            AND ja.selection_status = 'approved'        )      )  );$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_user_can_write CASCADE;CREATE OR REPLACE FUNCTION job_chat_user_can_write(  p_servicio_id UUID,  p_user_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM jobs j    WHERE j.id = p_servicio_id      AND j.status IN ('taken', 'in_progress')      AND (        job_chat_user_matches(j.created_by, p_user_id)        OR job_chat_user_matches(j.assigned_worker_id, p_user_id)        OR EXISTS (          SELECT 1          FROM job_assignments ja          WHERE ja.job_id = j.id            AND job_chat_user_matches(ja.worker_id, p_user_id)            AND ja.selection_status = 'approved'        )      )  );$$;DROP POLICY IF EXISTS mensajes_select_participant ON mensajes;CREATE POLICY mensajes_select_participant ON mensajes  FOR SELECT  USING (job_chat_is_participant(servicio_id));DROP POLICY IF EXISTS mensajes_insert_participant ON mensajes;CREATE POLICY mensajes_insert_participant ON mensajes  FOR INSERT  WITH CHECK (    job_chat_user_matches(remitente_id, auth.uid())    AND job_chat_is_writable(servicio_id)  );CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS send_job_chat_message CASCADE;CREATE OR REPLACE FUNCTION send_job_chat_message(  p_servicio_id UUID,  p_remitente_id UUID,  p_texto TEXT)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicSET row_security = onAS $$DECLARE  v_msg   mensajes%ROWTYPE;  v_text  TEXT;  v_uid   UUID := auth.uid();BEGIN  v_text := trim(p_texto);  IF char_length(v_text) = 0 OR char_length(v_text) > 2000 THEN    RETURN jsonb_build_object('success', false, 'error', 'El mensaje debe tener entre 1 y 2000 caracteres');  END IF;  IF v_uid IS NULL THEN    IF NOT job_chat_user_can_write(p_servicio_id, p_remitente_id) THEN      RETURN jsonb_build_object(        'success', false,        'error', 'Sesión requerida para enviar mensajes',        'code', 'auth_required'      );    END IF;  ELSIF NOT job_chat_user_matches(p_remitente_id, v_uid) THEN    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');  ELSIF NOT job_chat_user_can_write(p_servicio_id, p_remitente_id) THEN    RETURN jsonb_build_object(      'success', false,      'error', 'No podés enviar mensajes en este servicio (debe estar en curso y vos ser parte del mismo)',      'code', 'rls_denied'    );  END IF;  INSERT INTO mensajes (servicio_id, remitente_id, texto)  VALUES (p_servicio_id, p_remitente_id, v_text)  RETURNING * INTO v_msg;  RETURN jsonb_build_object(    'success', true,    'message', jsonb_build_object(      'id', v_msg.id,      'servicio_id', v_msg.servicio_id,      'remitente_id', v_msg.remitente_id,      'texto', v_msg.texto,      'creado_al', v_msg.creado_al    )  );EXCEPTION  WHEN insufficient_privilege THEN    RETURN jsonb_build_object(      'success', false,      'error', 'No autorizado por política de seguridad',      'code', 'rls_denied'    );END;$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_job_chat_messages CASCADE;CREATE OR REPLACE FUNCTION get_job_chat_messages(  p_servicio_id UUID,  p_caller_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicSET row_security = onAS $$DECLARE  v_messages JSONB;  v_uid UUID := auth.uid();BEGIN  IF v_uid IS NULL THEN    IF NOT job_chat_user_can_access(p_servicio_id, p_caller_id) THEN      RETURN jsonb_build_object(        'success', false,        'error', 'Sesión requerida para leer mensajes',        'code', 'auth_required'      );    END IF;  ELSIF NOT job_chat_user_matches(p_caller_id, v_uid) THEN    RETURN jsonb_build_object('success', false, 'error', 'No autorizado');  ELSIF NOT job_chat_user_can_access(p_servicio_id, p_caller_id) THEN    RETURN jsonb_build_object('success', false, 'error', 'No tenés acceso a esta conversación');  END IF;  SELECT COALESCE(    jsonb_agg(      jsonb_build_object(        'id', m.id,        'servicio_id', m.servicio_id,        'remitente_id', m.remitente_id,        'texto', m.texto,        'creado_al', m.creado_al      )      ORDER BY m.creado_al ASC    ),    '[]'::jsonb  )  INTO v_messages  FROM mensajes m  WHERE m.servicio_id = p_servicio_id;  RETURN jsonb_build_object('success', true, 'messages', v_messages);END;$$;REVOKE ALL ON FUNCTION send_job_chat_message(UUID, UUID, TEXT) FROM PUBLIC;REVOKE ALL ON FUNCTION get_job_chat_messages(UUID, UUID) FROM PUBLIC;GRANT EXECUTE ON FUNCTION send_job_chat_message(UUID, UUID, TEXT) TO anon, authenticated;GRANT EXECUTE ON FUNCTION get_job_chat_messages(UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION job_chat_user_can_access(UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION job_chat_user_can_write(UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION job_chat_user_matches(UUID, UUID) TO anon, authenticated;NOTIFY pgrst, 'reload schema';